func:
// 1. CLEAR CACHE WIPE OBJECTS
delete msg.url;
delete msg.payload;

// 2. RUNTIME CONFIGURATION
const apiKey = env.get("MARINESIA_API_KEY");
if (!apiKey) { node.status({ fill: "red", shape: "ring", text: "set MARINESIA_API_KEY in the tab env" }); return null; }
// GEOGRAPHIC TRACKING BOUNDARIES FOR TENNESSEE (+20 MILE BUFFER)
const lat_min = "33.5";
const lat_max = "38.0";
const long_min = "-92.5"; 
const long_max = "-79.5";

// GEOGRAPHIC TRACKING BOUNDARIES Reach the Gulf coast
// const lat_min = "30.0";
// const lat_max = "37.0";
// const long_min = "-92.5"; 
// const long_max = "-81.3";

// 3. COMPILE URL SEGMENTS
const domainParts = ["https://", "api", ".marinesia.com", "/api/v2/vessel/area"];
const baseUrl = domainParts.join("");

// 4. MAP DYNAMIC PARAMETERS TO MARINESIA PARSER FIELDS
msg.url = baseUrl + "?lat_min=" + lat_min + "&lat_max=" + lat_max + "&long_min=" + long_min + "&long_max=" + long_max + "&key=" + apiKey;
msg.method = "GET";
msg.headers = {
    "Accept": "application/json"
};

return msg;

try {
    function esc(s) {
        return String(s == null ? "" : s)
            .replace(/&/g, "&amp;").replace(/</g, "&lt;")
            .replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
    }

    // ---- 2525 Sea Surface function mapping ------------------------------
    // Confirmed against the real MIL-STD-2525 Sea Surface function table
    // (Surface/NON MILITARY branch a-.-S-X-*, and a-.-S-N-N-R for Rescue).
    // Marinesia's `type` string is matched case-sensitively against what
    // their API actually returns; unmapped/unknown types fall back to a
    // bare Non-Military surface track ('X') rather than being mislabeled
    // as Merchant, which is what EVERY vessel was getting before this fix.
    var SHIP_TYPE_MAP = {
        "Tug": "X-M-T-U",
        "Towing": "X-M-T-O",
        "Pleasure Craft": "X-R",
        "Fishing": "X-F",
        "Passenger": "X-M-P",
        "Cargo Ship": "X-M-C",
        "Cargo": "X-M-C",
        "Tanker": "X-M-O",
        "Ferry": "X-M-F",
        "Hazmat": "X-M-H",
        "Law Enforcement": "X-L",
        "Search and Rescue": "N-N-R",
        "Dredge": "X-F-D-R",
        "Trawler": "X-F-T-R"
        // "Uncategorized", "Other Type", and anything else not listed here
        // fall back to bare "X" (Non-Military surface track) below.
    };

    // ---- Affiliation by flag state --------------------------------------
    // Marinesia's `flag` field uses standard-ish 3-letter registry codes
    // (e.g. "USA", "MHL"). This is a STARTER list, same pattern as the
    // satellite/Winlink flows -- every CoT's remarks includes the raw flag
    // code, so watch real traffic and extend these as needed.
    var FRIENDLY_FLAGS = ["USA", "GBR", "CAN", "FRA", "DEU", "ITA", "ESP",
        "NLD", "BEL", "NOR", "DNK", "POL", "TUR", "PRT", "GRC", "CZE",
        "ROU", "HUN", "SVK", "HRV", "JPN", "AUS", "KOR", "NZL"];
    var HOSTILE_FLAGS = ["RUS", "CHN", "PRK", "CUB", "VNM", "LAO"];

    // ---- AIS navigational status codes (standard, 0-15) -----------------
    var NAV_STATUS = {
        0: "Underway (engine)", 1: "At anchor", 2: "Not under command",
        3: "Restricted maneuverability", 4: "Constrained by draught",
        5: "Moored", 6: "Aground", 7: "Fishing", 8: "Underway (sailing)",
        12: "Underway (sailing)", 15: "Not available"
    };

    let vessel = msg.payload;

    // Stop if data element is missing or incomplete
    if (!vessel || !vessel.mmsi) return null;

    let mmsi = vessel.mmsi;
    // Extract ship name cleanly (or use fallback string if blank)
    let shipName = vessel.name ? vessel.name.trim() : `MMSI: ${mmsi}`;

    // API coordinate data mapping 
    let lat = vessel.lat;
    let lon = vessel.lng; 

    // Block broken tracks from crashing your map engine
    if (lat === undefined || lon === undefined) return null;

    // Convert speed components (Knots to Meters per Second for TAK compliance)
    // AIS "not available" values: SOG 102.3 kn, COG 360 -- treat as 0
    let sogNum = Number(vessel.sog), cogNum = Number(vessel.cog);
    let speedKnots = (isFinite(sogNum) && sogNum >= 0 && sogNum < 102.2) ? sogNum : 0.0;
    let speedMetersPerSecond = speedKnots * 0.514444;
    let headingDegrees = (isFinite(cogNum) && cogNum >= 0 && cogNum < 360) ? cogNum : 0.0;

    // Set dynamic timestamps
    let time = new Date().toISOString();

    // EXTENDED CACHE WINDOW (CRUCIAL FOR LANDLOCKED WATERWAYS):
    // River barges move very slowly and you poll every 5 minutes. 
    // Setting stale window to 20 minutes ensures icons stay locked on screen between updates.
    let staleTime = new Date(Date.now() + 300000).toISOString(); 

    // ---- Coast Guard detection -------------------------------------------
    // Marinesia's `type` field for CG cutters is often just "Other Type"
    // (unhelpful), so detect via the vessel name instead -- US Coast Guard
    // vessels consistently broadcast names starting with "CG " or "USCGC "
    // (e.g. "CG OUACHITA" = USCGC Ouachita).
    let isCoastGuard = /^(USCGC|USCG|CG)\b/i.test(shipName);

    // ---- Determine affiliation from flag ---------------------------------
    let flagRaw = (vessel.flag || "UNKNOWN").toUpperCase();
    let aff = "u";
    if (FRIENDLY_FLAGS.indexOf(flagRaw) !== -1) aff = "f";
    else if (HOSTILE_FLAGS.indexOf(flagRaw) !== -1) aff = "h";
    if (isCoastGuard) { aff = "f"; } // government vessel -- friendly regardless of flag-list matching

    // ---- Determine 2525 function suffix from ship type --------------------
    let shipTypeRaw = vessel.type || "Uncategorized";
    let funcSuffix;
    if (isCoastGuard) {
        // Naval/Military branch ('N') instead of Non-Military ('X') --
        // same branch letter already confirmed and in use for Search and
        // Rescue above, just without a more specific sub-function since
        // Marinesia gives us nothing more granular to go on for CG cutters.
        funcSuffix = "N";
    } else {
        funcSuffix = SHIP_TYPE_MAP[shipTypeRaw] || "X-R";   // unmapped -> Pleasure Craft (civilian styling in CloudTAK)
    }

    let cotType = funcSuffix ? ("a-" + aff + "-S-" + funcSuffix) : ("a-" + aff + "-S");

    // ---- Build remarks with the extra context now available ---------------
    let remarksParts = [];
    remarksParts.push("Type: " + shipTypeRaw);
    if (isCoastGuard) { remarksParts.push("US Coast Guard (detected by name)"); }
    remarksParts.push("Flag: " + flagRaw);
    if (vessel.status !== undefined && vessel.status !== null) {
        let statusLabel = NAV_STATUS[vessel.status] || ("Code " + vessel.status);
        remarksParts.push("Status: " + statusLabel);
    }
    if (vessel.dest) remarksParts.push("Dest: " + vessel.dest);
    if (vessel.draught) remarksParts.push("Draught: " + vessel.draught + "m");
    let remarks = remarksParts.join(" | ");

    let cotXml = `<?xml version="1.0" encoding="UTF-8"?>\n` +
                 `<event version="2.0" uid="AIS-${mmsi}" type="${cotType}" time="${time}" start="${time}" stale="${staleTime}" how="m-g" access="P">\n` +
                 `  <point lat="${lat}" lon="${lon}" hae="0.0" ce="10.0" le="10.0"/>\n` +
                 `  <detail>\n` +
                 `    <contact callsign="${esc(shipName)}"/>\n` +
                 `    <track speed="${speedMetersPerSecond.toFixed(2)}" course="${headingDegrees.toFixed(1)}"/>\n` +
                 `    <remarks>${esc(remarks)}</remarks>\n` +
                 `  </detail>\n` +
                 `</event>\n`;

    msg.payload = cotXml;
    return msg;

} catch (e) {
    node.error("Marinesia CoT Conversion Exception: " + e.message);
    return null;
}
